<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>مدیریت کاربران | Haman Planner</title><style>body{margin:0;background:#f4f6f9;color:#172033;font-family:system-ui}.wrap{max-width:1100px;margin:30px auto;padding:20px}.card{background:#fff;border:1px solid #e2e7ee;border-radius:16px;padding:20px;margin-bottom:15px}.head{display:flex;justify-content:space-between;align-items:center}.btn{border:1px solid #d5dbe4;background:#fff;border-radius:9px;padding:9px 13px;font-weight:700}.primary{background:#172033;color:#fff}.danger{color:#b42318}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:11px;border-bottom:1px solid #e5e9ef;text-align:right;font-size:13px}.field{margin:10px 0}.field label{display:block;font-size:12px;font-weight:700;margin-bottom:5px}.field input{width:100%;padding:9px;border:1px solid #d5dbe4;border-radius:9px;box-sizing:border-box}.token{background:#fff7d6;border:1px solid #e8d58b;padding:12px;border-radius:10px;word-break:break-all}.modal{display:none;position:fixed;inset:0;background:#0007;align-items:center;justify-content:center;padding:20px}.modal.show{display:flex}.box{background:#fff;border-radius:16px;padding:22px;width:min(520px,100%)}.actions{display:flex;gap:7px;margin-top:14px}</style></head><body><div class=wrap><div class=head><div><h1>مدیریت کاربران و API Token</h1><p>فقط مدیر سیستم به این بخش دسترسی دارد.</p></div><div><a class=btn href="{{route('account.settings')}}">امنیت و تغییر رمز</a> <a class=btn href="{{route('admin.home')}}">پنل مدیریت</a> <a class=btn href="{{route('planner.app')}}">بازگشت</a></div></div><div class=card><div class=head><h2>کاربران</h2><button class="btn primary" onclick="userForm()">＋ کاربر</button></div><div id=users></div></div><div class=card><div class=head><h2>API Tokens</h2><button class="btn primary" onclick="tokenForm()">＋ Token</button></div><div id=tokens></div></div></div><div class=modal id=modal><div class=box id=box></div></div><script>const csrf=document.querySelector('meta[name=csrf-token]')?.content;async function api(p,o={}){let h={'Accept':'application/json','X-CSRF-TOKEN':csrf,...(o.headers||{})};if(o.method&&o.method!=='GET')h['Content-Type']='application/json';let r=await fetch('/api'+p,{...o,headers:h,credentials:'same-origin'});if(!r.ok){let x={};try{x=await r.json()}catch{};throw Error(x.message||Object.values(x.errors||{}).flat().join(' ')||'خطا')}return r.status===204?null:r.json()}const esc=v=>String(v??'').replace(/[&<>"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]));async function load(){let u=await api('/admin/users'),t=await api('/admin/tokens');document.querySelector('#users').innerHTML='<table class=table><tr><th>نام</th><th>ایمیل</th><th>نقش</th><th>وضعیت</th><th></th></tr>'+u.map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+esc(x.email)+'</td><td>'+(x.is_admin?'Admin':'User')+'</td><td>'+(x.is_active?'فعال':'غیرفعال')+'</td><td><button class=btn onclick="editUser('+x.id+')">ویرایش</button> <button class="btn danger" onclick="delUser('+x.id+')">حذف</button></td></tr>').join('')+'</table>';document.querySelector('#tokens').innerHTML=t.map(x=>'<div style="padding:10px;border-bottom:1px solid #eee"><b>'+esc(x.name)+'</b> · '+esc(x.token_prefix)+'… · '+(x.last_used_at||'استفاده نشده')+' <button class="btn danger" onclick="revoke('+x.id+')">لغو</button></div>').join('')||'<p>Token فعالی وجود ندارد.</p>'}function show(h){document.querySelector('#box').innerHTML=h;document.querySelector('#modal').classList.add('show')}function closeModal(){document.querySelector('#modal').classList.remove('show')}function userForm(x={}){show('<h2>'+(x.id?'ویرایش':'کاربر جدید')+'</h2><form id=f><div class=field><label>نام</label><input name=name required value="'+esc(x.name||'')+'"></div><div class=field><label>ایمیل</label><input name=email type=email required value="'+esc(x.email||'')+'"></div><div class=field><label>رمز عبور '+(x.id?'(خالی = بدون تغییر)':'')+'</label><input name=password type=password '+(x.id?'':'required')+'></div><label><input type=checkbox name=is_admin '+(x.is_admin?'checked':'')+'> مدیر</label> <label><input type=checkbox name=is_active '+(x.is_active!==false?'checked':'')+'> فعال</label><div class=actions><button class="btn primary">ذخیره</button><button type=button class=btn onclick=closeModal()>انصراف</button></div></form>');document.querySelector('#f').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));d.is_admin=e.target.is_admin.checked;d.is_active=e.target.is_active.checked;if(!d.password)delete d.password;try{await api('/admin/users'+(x.id?'/'+x.id:''),{method:x.id?'PUT':'POST',body:JSON.stringify(d)});closeModal();load()}catch(z){alert(z.message)}}}async function editUser(id){let u=await api('/admin/users');userForm(u.find(x=>x.id===id))}async function delUser(id){if(confirm('حذف کاربر؟')){try{await api('/admin/users/'+id,{method:'DELETE'});load()}catch(e){alert(e.message)}}}function tokenForm(){show('<h2>ساخت API Token</h2><form id=f><div class=field><label>نام Token</label><input name=name required placeholder="Telegram / Integration"></div><div class=field><label>انقضا</label><input name=expires_at type=datetime-local></div><div class=actions><button class="btn primary">ساخت</button><button type=button class=btn onclick=closeModal()>انصراف</button></div></form>');document.querySelector('#f').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(!d.expires_at)d.expires_at=null;try{let r=await api('/admin/tokens',{method:'POST',body:JSON.stringify(d)});show('<h2>Token ساخته شد</h2><p>این مقدار فقط همین بار نمایش داده می‌شود:</p><div class=token>'+esc(r.token)+'</div><div class=actions><button class="btn primary" onclick=closeModal();load()>بستن</button></div>')}catch(z){alert(z.message)}}}async function revoke(id){if(confirm('این Token لغو شود؟')){await api('/admin/tokens/'+id,{method:'DELETE'});load()}}load();</script></body></html>